head.script:
scwin.onpageload = function() {
    $p.getFormattedDate(new Date(1626073377000), "yyyy년 MM월 dd일 (E) HH:mm:ss");
    console.log("Date 오전 9시 전 : " + $p.getFormattedDate(new Date(1626047977000), "yyyy년 MM월 dd일 (E) HH:mm:ss"));
    console.log("Date 오전 9시 후 : " + $p.getFormattedDate(new Date(1626048077000), "yyyy년 MM월 dd일 (E) HH:mm:ss"));
    var temp = "Date 오전 9시 후 : " + $p.getFormattedDate(new Date(1626048077000), "yyyy년 MM월 dd일 (E) HH:mm:ss")
	window.log = temp.indexOf('월');
};
scwin.onpageunload = function() {};
scwin.checkVal = function() {
	return window.log > 0;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    localStorage.removeItem("log");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
